public class ArrayIntro {
    public static void main(String[] args) {
        // One array replaces 4 individual temperature variables
        int[] temperatures = new int[4];

        temperatures[0] = 72; // Day 1
        temperatures[1] = 68; // Day 2
        temperatures[2] = 75; // Day 3
        temperatures[3] = 81; // Day 4

        System.out.println("Day 1 Temp: " + temperatures[0] + " F");
        System.out.println("Day 4 Temp: " + temperatures[3] + " F");

        // The .length property holds the capacity
        System.out.println("Total Recorded Days: " + temperatures.length);
    }
}

