practiceProblems.solutionCode:
public class Main {
    public static void displayHeadAndTail(int[] arr) {
        System.out.println("Head: " + arr[0] + " | Tail: " + arr[arr.length - 1]);
    }

    public static void main(String[] args) {
        int[] data = new int[4];
        data[0] = 10;
        data[1] = 20;
        data[2] = 30;
        data[3] = 40;
        displayHeadAndTail(data);
    }
}

