public class Main {
    public static void main(String[] args) {
        int[] arr = new int[3];
        arr[0] = 100;
        arr[1] = 200;
        arr[2] = 300;

        int temp = arr[0];
        arr[0] = arr[2];
        arr[2] = temp;

        System.out.println("After Swap: arr[0]=" + arr[0] + ", arr[2]=" + arr[2]);
    }
}
